/**
 * overrides.js — 院內規範覆寫（HR-UX-1）
 *
 * OverrideRules = Map<rule_key, value>
 * rule_key 與 0005 migration + apps/etp override-rules route 的 whitelist 對齊。
 *
 * 計算引擎（severance-traced / overtime-traced / leave 等）接受 `overrides` 參數，
 * 透過 resolveRate / resolveMonths / resolveDays 取代法規預設值。
 *
 * 設計原則：
 * - 覆寫值必須「優於或等於」法規（由 API 端 validateRuleValue 守門 + 本檔 floor 保險）
 * - 回傳 { value, overridden: boolean, source: 'legal' | 'override', sourceRef?, note? }
 *   讓 trace 的 step / laws 能標記清楚
 */

/** 法規下限 constants（與 /api/[workspace]/override-rules 的 validateRuleValue 對齊） */
export const LEGAL_FLOOR = Object.freeze({
  overtime_rate_weekday_h1_h2: 4 / 3,
  overtime_rate_weekday_h3_h4: 5 / 3,
  overtime_rate_restday_h1_h2: 4 / 3,
  overtime_rate_restday_h2_h8: 5 / 3,
  overtime_rate_holiday: 2.0,
  severance_base_per_year_months: 0.5,
  severance_cap_months: 6,
  leave_marriage_days: 8,
  leave_menstrual_pay_rate: 0.5,
});

/**
 * 解析某 rule_key 的實際生效值（優先用 overrides；沒有則回法規下限）
 *
 * @param {Object|undefined} overrides   從 DB `workspace_override_rules` 拉出的 rules map
 *                                       { 'overtime.rate_weekday_h1_h2': { value: {rate: 1.5}, note, source_ref, is_active }, ... }
 * @param {string} ruleKey               namespaced key（'overtime.rate_weekday_h1_h2' 等）
 * @param {string} valuePath             value 物件中要抽的路徑（'rate' / 'days' / 'months'）
 * @param {number} legalFloor            法規下限（如 4/3）
 * @returns {{
 *   value: number,
 *   overridden: boolean,
 *   source: 'legal' | 'override',
 *   sourceRef?: string,
 *   note?: string,
 * }}
 */
export function resolveValue(overrides, ruleKey, valuePath, legalFloor) {
  if (!overrides) return { value: legalFloor, overridden: false, source: 'legal' };

  const rule = overrides[ruleKey];
  if (!rule || rule.is_active === false) {
    return { value: legalFloor, overridden: false, source: 'legal' };
  }

  const rawValue = rule.value;
  let resolved = null;
  if (typeof rawValue === 'number' && Number.isFinite(rawValue)) {
    resolved = rawValue;
  } else if (typeof rawValue === 'object' && rawValue !== null) {
    const v = rawValue[valuePath];
    if (typeof v === 'number' && Number.isFinite(v)) resolved = v;
  }

  if (resolved === null) {
    return { value: legalFloor, overridden: false, source: 'legal' };
  }

  // 保險：即使 API 層漏擋，本處仍強制不低於法規（defence-in-depth）
  // 但對 marriage/sick 這類「多給」型，allow 低於不合理，由 API 驗；本處只保倍率/基數類
  if (resolved < legalFloor - 0.001) {
    return { value: legalFloor, overridden: false, source: 'legal' };
  }

  return {
    value: resolved,
    overridden: true,
    source: 'override',
    sourceRef: rule.source_ref ?? undefined,
    note: rule.note ?? undefined,
  };
}

/**
 * 加班倍率的 convenience wrapper（最常用）
 */
export function resolveOvertimeRate(overrides, kind) {
  const map = {
    weekday_h1_h2: ['overtime.rate_weekday_h1_h2', LEGAL_FLOOR.overtime_rate_weekday_h1_h2],
    weekday_h3_h4: ['overtime.rate_weekday_h3_h4', LEGAL_FLOOR.overtime_rate_weekday_h3_h4],
    restday_h1_h2: ['overtime.rate_restday_h1_h2', LEGAL_FLOOR.overtime_rate_restday_h1_h2],
    restday_h2_h8: ['overtime.rate_restday_h2_h8', LEGAL_FLOOR.overtime_rate_restday_h2_h8],
    holiday: ['overtime.rate_holiday', LEGAL_FLOOR.overtime_rate_holiday],
  };
  const entry = map[kind];
  if (!entry) throw new Error(`unknown overtime kind: ${kind}`);
  return resolveValue(overrides, entry[0], 'rate', entry[1]);
}

/**
 * 資遣基數 / 上限
 */
export function resolveSeveranceBase(overrides) {
  return resolveValue(
    overrides,
    'severance.base_per_year_months',
    'months',
    LEGAL_FLOOR.severance_base_per_year_months,
  );
}
export function resolveSeveranceCap(overrides) {
  return resolveValue(
    overrides,
    'severance.cap_months',
    'months',
    LEGAL_FLOOR.severance_cap_months,
  );
}
