/**
 * insurance.js — 雇主社保成本計算（勞保 / 勞退 / 職災 / 健保）
 *
 * ## 法源（2026 版）
 * - 勞保費率 12.5% = 普通事故 11.5% + 就業保險 1%（勞動部 114 年底公告）
 * - 職災保險平均費率 0.21%（⚠️ 實際因行業別而異，0.04%~1.13%）
 * - 健保費率 5.17%（2021/1/1 沿用）
 * - 勞退月提繳費率 6%（勞退條例§14）
 */

import {
  getLaborInsuranceBracket,
  getNhiBracket,
  getPensionBracket,
  getWorkInjuryBracket,
} from './brackets.js';

/**
 * 2026 年社保費率（驗證來源：勞動部、衛福部 114 年底公告）
 */
export const LABOR_RATES_2026 = {
  /** 勞保費率 12.5% = 普通事故 11.5% + 就業保險 1% */
  labor: 0.125,
  /** 勞保費率：勞工自付 20% */
  laborEmployee: 0.20,
  /** 勞保費率：雇主負擔 70% */
  laborEmployer: 0.70,
  /** 勞保費率：政府補助 10% */
  laborGovt: 0.10,
  /** 職災保險平均費率 0.21%（⚠️ 實際因行業別而異，0.04%~1.13%；請勞保局查行業別碼確認
   *  法源：勞工職業災害保險及保護法§16 + 職業災害保險適用行業別及費率表）*/
  accident: 0.0021,
  /** 健保費率 5.17%（2021/1/1 調整後沿用） */
  nhi: 0.0517,
  /** 健保雇主負擔 60% */
  nhiEmployer: 0.60,
  /** 健保受僱者負擔 30%（餘 10% 政府） */
  nhiEmployee: 0.30,
  /** 勞退月提繳費率 6%（勞退條例§14） */
  pension: 0.06,
  /** 健保平均眷屬口數（2024 衛福部公告） */
  nhiAvgDependents: 0.58,
};

/**
 * 雇主社保成本計算（2026 版）
 *
 * 勞保與健保分別用自己的級距表：
 * - 勞保：LABOR_INSURANCE_BRACKETS_2026（11 級，上限 45,800）
 * - 健保：NHI_BRACKETS_2026（58 級，上限 313,000）
 * - 勞退：PENSION_BRACKETS_2026（62 級，上限 150,000）
 * - 職災：WORK_INJURY_BRACKETS_2026（21 級，上限 72,800）
 *
 * @param {number} monthlySalary 月薪（實際薪資）
 * @param {number|null} dependents 眷屬人數；若為 null 則套用平均 0.58 人
 * @returns {{ laborIns: number, laborAccident: number, nhi: number, pension: number, total: number, bracket: number, nhiBracket: number, pensionBracket: number, workInjuryBracket: number }}
 */
export function calcEmployerInsuranceCost(monthlySalary, dependents) {
  const bracket = getLaborInsuranceBracket(monthlySalary);
  const nhiBracket = getNhiBracket(monthlySalary);
  const pensionBracket = getPensionBracket(monthlySalary);
  const workInjuryBracket = getWorkInjuryBracket(monthlySalary);
  const R = LABOR_RATES_2026;
  const depCount = (dependents == null) ? R.nhiAvgDependents : dependents;

  const laborIns = Math.round(bracket * R.labor * R.laborEmployer);
  // 職災保險使用獨立分級表（非勞保 11 級）
  const laborAccident = Math.round(workInjuryBracket * R.accident);
  // 健保本人 + 眷屬：實務上眷屬以平均 0.58 人計；超過 3 口者以 3 口封頂（健保法§27）
  const effectiveDep = Math.min(depCount, 3);
  const nhi = Math.round(nhiBracket * R.nhi * R.nhiEmployer * (1 + effectiveDep));
  // 勞退使用獨立分級表（上限 150,000）
  const pension = Math.round(pensionBracket * R.pension);

  return {
    laborIns,
    laborAccident,
    nhi,
    pension,
    total: laborIns + laborAccident + nhi + pension,
    bracket,
    nhiBracket,
    pensionBracket,
    workInjuryBracket,
  };
}
