/**
 * trace.js — 計算過程 trace 共用型別與 helper
 *
 * ## 為何存在
 * HR Pro 需求（HR-UX-2, P0）：計算結果不只給數字，要攤開每步公式 + 代入值 + 法源。
 * 民眾版 laborpro 的既有函式維持 signature 不動（零缺陷鐵律），新加 `*Traced` 版本
 * 返回 `{ result, trace }`，供 HR Pro UI 展開「計算過程」面板。
 *
 * ## 設計原則
 * - 純函式、無 side effect
 * - Trace 物件可直接 JSON serialize，給前端 / PDF render 用
 * - steps / laws 為 array 順序即顯示順序
 *
 * @see HR-UX-2 in master-plan.md §8.A
 */

/**
 * @typedef {Object} CalcStep
 * @property {string} label            - 步驟描述（給人看）
 * @property {string} formula          - 公式字串（如 "totalMonths / 12 * 0.5"）
 * @property {Record<string, number>} [inputs]  - 代入值
 * @property {number} value            - 此步計算結果
 * @property {string} [note]           - 補充說明（如「上限 6 個月」）
 */

/**
 * @typedef {Object} LawRef
 * @property {string} article      - 條號（如 "勞退條例§12"）
 * @property {string} description  - 一行說明
 * @property {string} [url]        - 全國法規資料庫連結（選填）
 */

/**
 * @typedef {Object} CalcTrace
 * @property {CalcStep[]} steps    - 按順序的計算步驟
 * @property {LawRef[]} laws       - 引用法條（去重）
 * @property {string} summary      - 一句話 TL;DR（如「新制資遣費 45,000 元」）
 */

/**
 * @typedef {Object} TracedResult
 * @property {number} result       - 最終金額 / 天數 / 其他數值
 * @property {CalcTrace} trace
 */

/**
 * 建立 trace 骨架，呼叫端 push steps / laws 後返回。
 * @returns {CalcTrace}
 */
export function createTrace() {
  return { steps: [], laws: [], summary: '' };
}

/**
 * Push 一個步驟（回傳 trace 以支援 chain）
 * @param {CalcTrace} trace
 * @param {CalcStep} step
 * @returns {CalcTrace}
 */
export function addStep(trace, step) {
  trace.steps.push(step);
  return trace;
}

/**
 * Push 一個法源（自動去重，以 article 為 key）
 * @param {CalcTrace} trace
 * @param {LawRef} law
 * @returns {CalcTrace}
 */
export function addLaw(trace, law) {
  if (!trace.laws.some((l) => l.article === law.article)) {
    trace.laws.push(law);
  }
  return trace;
}

/**
 * 設 summary
 * @param {CalcTrace} trace
 * @param {string} summary
 * @returns {CalcTrace}
 */
export function setSummary(trace, summary) {
  trace.summary = summary;
  return trace;
}
