/**
 * hourly.js — 小時工計薪（餐飲 / 計時人員）traced 版本
 *
 * ## 為何存在
 * 餐飲 workspace.type='restaurant' 大量小時工 / 計時人員，月薪制換算的 §24 OT 公式不適用。
 * 本檔提供 hourlyRate 直接代入版本，並把法定基本時薪（勞動部公告）做下限驗證。
 *
 * ## 法源（每條已於全國法規資料庫驗證；版本以 LATEST_HOURLY_VERSION 標示）
 * - 勞基法§21 工資由勞雇雙方議定，不得低於基本工資
 * - 勞基法§24 I  平日延長工時加成（前 2h × 4/3、第 3-4h × 5/3）
 * - 勞基法§37、§39 國定假日加倍工資
 * - 勞基法§36、§40 例假日（七休一）原則上不得使勞工工作
 *
 * ## 基本時薪版本表
 * 114 年起（2025/1/1～）— 勞動部 113.9.4 勞動條 2 字第 1130150982 號公告
 *   月薪 NT$ 28,590 / 時薪 NT$ 190
 * 115 年起（2026/1/1～）— 勞動部 114.9.4 公告
 *   月薪 NT$ 29,500 / 時薪 NT$ 196
 *   （本系統 brackets.js 已採此版作為勞保投保下限第 11 級 29,500）
 *
 * ## 設計
 *  - calcHourlyWage 不直接呼叫 calcOvertimeCost（因小時工是時薪非月薪），
 *    自行依 §24 / §39 倍率計算。
 *  - overrides 採與 overtime-traced.js 一致的 LEGAL_FLOOR + resolveOvertimeRate 介面。
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { resolveOvertimeRate, LEGAL_FLOOR } from './overrides.js';

/**
 * 法定基本時薪歷年公告（最新者最後）。
 * 新版上路時 push 一筆並更新 LATEST_HOURLY_VERSION。
 */
export const MIN_HOURLY_WAGE_VERSIONS = Object.freeze([
  Object.freeze({
    year: 114,
    effectiveFrom: '2025-01-01',
    monthly: 28590,
    hourly: 190,
    publishedAt: '2024-09-04',
    publishNo: '勞動部 113.9.4 勞動條 2 字第 1130150982 號',
  }),
  Object.freeze({
    year: 115,
    effectiveFrom: '2026-01-01',
    monthly: 29500,
    hourly: 196,
    publishedAt: '2025-09-04',
    publishNo: '勞動部 114.9.4 公告（待補正式字號）',
  }),
]);

/** 目前生效版本（最新一筆） */
export const LATEST_HOURLY_VERSION =
  MIN_HOURLY_WAGE_VERSIONS[MIN_HOURLY_WAGE_VERSIONS.length - 1];

/** 法定基本時薪（最新版） */
export const MIN_HOURLY_WAGE = LATEST_HOURLY_VERSION.hourly;

/**
 * @typedef {Object} HourlyWageInput
 * @property {number} hours              — 平日正常工時時數
 * @property {number} hourlyRate         — 議定時薪（不得低於 MIN_HOURLY_WAGE）
 * @property {number} [otHours]          - 平日延長工時（§24 I）
 * @property {number} [holidayHours]     - 國定假日出勤時數（§37、§39 加倍）
 * @property {number} [regularOffHours]  - 例假 / 休息日出勤時數（§36 → §24 II 階梯，本檔簡化為 holiday 倍率）
 * @property {Object} [overrides]        - 院內規範覆寫（同 calcOvertimeCostTraced）
 * @property {number} [referenceDate]    - Reserved，未使用
 */

/**
 * 小時工 / 計時人員工資計算（traced）
 *
 * @param {HourlyWageInput} params
 * @returns {import('./trace.js').TracedResult}
 */
export function calcHourlyWage(params) {
  const {
    hours,
    hourlyRate,
    otHours = 0,
    holidayHours = 0,
    regularOffHours = 0,
    overrides,
  } = params;

  if (typeof hours !== 'number' || hours < 0) {
    throw new Error('calcHourlyWage: invalid hours');
  }
  if (typeof hourlyRate !== 'number' || hourlyRate <= 0) {
    throw new Error('calcHourlyWage: invalid hourlyRate');
  }

  const trace = createTrace();

  // ── 法源 ──
  addLaw(trace, {
    article: '勞基法§21 I',
    description: '工資由勞雇雙方議定，但不得低於基本工資',
  });
  addLaw(trace, {
    article: `${LATEST_HOURLY_VERSION.publishNo}`,
    description: `${LATEST_HOURLY_VERSION.year} 年起基本時薪 NT$ ${LATEST_HOURLY_VERSION.hourly}（${LATEST_HOURLY_VERSION.effectiveFrom} 生效）`,
  });

  // ── 基本時薪驗證 ──
  const minHourly = LATEST_HOURLY_VERSION.hourly;
  const belowMin = hourlyRate < minHourly;
  addStep(trace, {
    label: '基本時薪檢核',
    formula: `hourlyRate (${hourlyRate}) ≥ MIN_HOURLY_WAGE (${minHourly})`,
    inputs: { hourlyRate, minHourly },
    value: belowMin ? 0 : 1,
    note: belowMin
      ? `⚠️ 議定時薪 ${hourlyRate} 低於 ${LATEST_HOURLY_VERSION.year} 年法定基本時薪 ${minHourly}（§21 I 違法），下方仍依議定值計算供比對`
      : `符合 ${LATEST_HOURLY_VERSION.year} 年基本時薪下限 ${minHourly}`,
  });

  // ── 平日正常工時 ──
  const regularPay = hours * hourlyRate;
  if (hours > 0) {
    addStep(trace, {
      label: '平日正常工時工資',
      formula: 'hours × hourlyRate',
      inputs: { hours, hourlyRate },
      value: regularPay,
    });
  }

  // ── 平日延長工時（§24 I） ──
  let otPay = 0;
  if (otHours > 0) {
    addLaw(trace, {
      article: '勞基法§24 I',
      description: '平日延長工時前 2 小時加給 1/3；第 3-4 小時加給 2/3',
    });
    const r1 = resolveOvertimeRate(overrides, 'weekday_h1_h2');
    const r2 = resolveOvertimeRate(overrides, 'weekday_h3_h4');
    const h1 = Math.min(otHours, 2);
    const h2 = Math.max(Math.min(otHours - 2, 2), 0);
    const otPay1 = h1 * hourlyRate * r1.value;
    const otPay2 = h2 * hourlyRate * r2.value;
    otPay = otPay1 + otPay2;
    if (h1 > 0) {
      addStep(trace, {
        label: '延長前 2 小時',
        formula: `h1 × hourlyRate × ${r1.value.toFixed(3)}`,
        inputs: { h1, hourlyRate, rate: r1.value },
        value: otPay1,
        note: r1.overridden
          ? `院內倍率 ${r1.value}（法規 ${LEGAL_FLOOR.overtime_rate_weekday_h1_h2.toFixed(3)}）`
          : '前 2 小時加給 1/3（§24 I 一款）',
      });
    }
    if (h2 > 0) {
      addStep(trace, {
        label: '延長第 3-4 小時',
        formula: `h2 × hourlyRate × ${r2.value.toFixed(3)}`,
        inputs: { h2, hourlyRate, rate: r2.value },
        value: otPay2,
        note: r2.overridden
          ? `院內倍率 ${r2.value}（法規 ${LEGAL_FLOOR.overtime_rate_weekday_h3_h4.toFixed(3)}）`
          : '第 3-4 小時加給 2/3（§24 I 二款）',
      });
    }
  }

  // ── 國定假日（§37、§39） ──
  let holidayPay = 0;
  if (holidayHours > 0) {
    addLaw(trace, {
      article: '勞基法§37、§39',
      description: '紀念日 / 節日 / 勞動節應放假；經勞工同意工作者，工資應加倍發給',
    });
    const rh = resolveOvertimeRate(overrides, 'holiday');
    holidayPay = holidayHours * hourlyRate * rh.value;
    addStep(trace, {
      label: '國定假日出勤',
      formula: `holidayHours × hourlyRate × ${rh.value}`,
      inputs: { holidayHours, hourlyRate, rate: rh.value },
      value: holidayPay,
      note: rh.overridden
        ? `院內倍率 ${rh.value}（法規 ${LEGAL_FLOOR.overtime_rate_holiday}）`
        : '工資加倍發給（§39）',
    });
  }

  // ── 例假日 / 休息日（§36、§40） ──
  let regularOffPay = 0;
  if (regularOffHours > 0) {
    addLaw(trace, {
      article: '勞基法§36、§40',
      description: '例假非天災事變突發事件不得使勞工工作；§40 停止假期工資加倍發給並給予事後補假',
    });
    const rh = resolveOvertimeRate(overrides, 'holiday');
    regularOffPay = regularOffHours * hourlyRate * rh.value;
    addStep(trace, {
      label: '例假 / 休息日出勤（簡化版）',
      formula: `regularOffHours × hourlyRate × ${rh.value}`,
      inputs: { regularOffHours, hourlyRate, rate: rh.value },
      value: regularOffPay,
      note:
        '⚠️ §36 七休一原則例假不得出勤；本欄供§40 三事由（天災 / 事變 / 突發事件）試算最低補償。' +
        '休息日階梯（前 2h × 4/3、2-8h × 5/3、超 8h × 5/3）請改用 calcOvertimeCost(restday)。',
    });
  }

  const total = regularPay + otPay + holidayPay + regularOffPay;
  addStep(trace, {
    label: '合計工資',
    formula: 'regularPay + otPay + holidayPay + regularOffPay',
    inputs: {
      regularPay,
      otPay,
      holidayPay,
      regularOffPay,
    },
    value: total,
  });

  setSummary(
    trace,
    `小時工合計 NT$ ${Math.round(total).toLocaleString()}` +
      (belowMin ? ` · ⚠️ 議定時薪低於 ${minHourly}` : ''),
  );

  return { result: total, trace };
}
