/**
 * overtime-traced.js — 加班費帶計算過程版本
 *
 * 民眾版 laborpro 繼續用 `overtime.js` 原函式。
 * HR Pro 用本 module 的 `calcOvertimeCostTraced` 取得 steps + laws。
 */

import { calcOvertimeCost } from './overtime.js';
import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { resolveOvertimeRate, LEGAL_FLOOR } from './overrides.js';

/**
 * 加班費帶 trace（HR-UX-1: options.overrides 院內規範覆寫）
 * @param {number} monthlySalary
 * @param {number} hours
 * @param {'weekday'|'restday'|'mixed'|'holiday'} type
 * @param {Object} [options]
 * @param {Object} [options.overrides]
 * @returns {import('./trace.js').TracedResult}
 */
export function calcOvertimeCostTraced(monthlySalary, hours, type, options = {}) {
  const overrides = options.overrides;
  const trace = createTrace();
  const hourly = monthlySalary / 30 / 8;

  addStep(trace, {
    label: '時薪換算',
    formula: 'monthlySalary / 30 / 8',
    inputs: { monthlySalary },
    value: hourly,
    note: '月薪換算時薪（§24 計算基礎）',
  });

  if (type === 'weekday') {
    addLaw(trace, {
      article: '勞基法§24 I',
      description: '平日延長工時前 2 小時加給 1/3；第 3-4 小時加給 2/3',
    });
    const r1 = resolveOvertimeRate(overrides, 'weekday_h1_h2');
    const r2 = resolveOvertimeRate(overrides, 'weekday_h3_h4');
    addOverrideLaws(trace, [r1, r2], ['平日前2小時', '平日3-4小時']);

    const h1 = Math.min(hours, 2);
    const h2 = Math.max(Math.min(hours - 2, 2), 0);
    const pay1 = h1 * hourly * r1.value;
    const pay2 = h2 * hourly * r2.value;
    const total = pay1 + pay2;

    if (h1 > 0) {
      addStep(trace, {
        label: '平日延長前 2 小時',
        formula: `h1 × hourly × ${r1.value.toFixed(3)}`,
        inputs: { h1, hourly, rate: r1.value },
        value: pay1,
        note: r1.overridden
          ? `貴院倍率 ${r1.value}（法規 ${LEGAL_FLOOR.overtime_rate_weekday_h1_h2.toFixed(3)}）`
          : '前 2 小時加給 1/3（§24 I 一款）',
      });
    }
    if (h2 > 0) {
      addStep(trace, {
        label: '平日延長第 3-4 小時',
        formula: `h2 × hourly × ${r2.value.toFixed(3)}`,
        inputs: { h2, hourly, rate: r2.value },
        value: pay2,
        note: r2.overridden
          ? `貴院倍率 ${r2.value}（法規 ${LEGAL_FLOOR.overtime_rate_weekday_h3_h4.toFixed(3)}）`
          : '第 3-4 小時加給 2/3（§24 I 二款）',
      });
    }
    addStep(trace, { label: '平日加班費總計', formula: 'pay1 + pay2', value: total });
    setSummary(
      trace,
      `平日加班 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元` +
        (r1.overridden || r2.overridden ? ' · 套用院內規範' : '')
    );
    verify(total, monthlySalary, hours, type, r1.overridden || r2.overridden);
    return { result: total, trace };
  }

  if (type === 'restday') {
    addLaw(trace, {
      article: '勞基法§24 II、§36',
      description: '休息日出勤前 2 小時加給 1/3，2-8 小時加給 2/3，逾 8 小時亦加給 2/3',
    });
    addLaw(trace, {
      article: '勞動部 106.6.16 勞動條 2 字第 1060131319 號函',
      description: '休息日超過 2 小時之加成率細節',
    });
    const rr1 = resolveOvertimeRate(overrides, 'restday_h1_h2');
    const rr2 = resolveOvertimeRate(overrides, 'restday_h2_h8');
    addOverrideLaws(trace, [rr1, rr2], ['休息日前2小時', '休息日2-8小時']);

    const r1 = Math.min(hours, 2);
    const r2 = Math.max(Math.min(hours - 2, 6), 0);
    const r3 = Math.max(hours - 8, 0);
    const p1 = r1 * hourly * rr1.value;
    const p2 = r2 * hourly * rr2.value;
    const p3 = r3 * hourly * rr2.value;
    const total = p1 + p2 + p3;

    if (r1 > 0) addStep(trace, { label: '休息日前 2 小時', formula: `r1 × hourly × ${rr1.value.toFixed(3)}`, inputs: { r1, hourly, rate: rr1.value }, value: p1 });
    if (r2 > 0) addStep(trace, { label: '休息日 2-8 小時', formula: `r2 × hourly × ${rr2.value.toFixed(3)}`, inputs: { r2, hourly, rate: rr2.value }, value: p2 });
    if (r3 > 0) addStep(trace, { label: '休息日逾 8 小時', formula: `r3 × hourly × ${rr2.value.toFixed(3)}`, inputs: { r3, hourly, rate: rr2.value }, value: p3 });
    addStep(trace, { label: '休息日加班費總計', formula: 'p1 + p2 + p3', value: total });
    setSummary(trace, `休息日出勤 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元` + (rr1.overridden || rr2.overridden ? ' · 套用院內規範' : ''));
    verify(total, monthlySalary, hours, type, rr1.overridden || rr2.overridden);
    return { result: total, trace };
  }

  if (type === 'holiday') {
    addLaw(trace, { article: '勞基法§37、§39', description: '國定假日工作加發一日工資（雙倍）' });
    addLaw(trace, { article: '勞基法§36、§40', description: '例假日非天災事變不得使勞工工作；出勤以加倍工資處理' });
    const rh = resolveOvertimeRate(overrides, 'holiday');
    addOverrideLaws(trace, [rh], ['國定/例假倍率']);
    const total = hours * hourly * rh.value;
    addStep(trace, {
      label: '國定/例假出勤',
      formula: `hours × hourly × ${rh.value}`,
      inputs: { hours, hourly, rate: rh.value },
      value: total,
      note: rh.overridden
        ? `貴院倍率 ${rh.value}（法規 ${LEGAL_FLOOR.overtime_rate_holiday}）`
        : '本函式以雙倍計（§37、§39）',
    });
    setSummary(
      trace,
      `國定/例假出勤 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元（${rh.value}x）` +
        (rh.overridden ? ' · 套用院內規範' : '')
    );
    verify(total, monthlySalary, hours, type, rh.overridden);
    return { result: total, trace };
  }

  // mixed
  addLaw(trace, {
    article: '勞基法§24 I、II、§36',
    description: '混合類型：6 成平日 + 4 成休息日加權計算（內部估算用）',
  });
  const wdH = hours * 0.6;
  const rdH = hours * 0.4;
  const wdPay = calcOvertimeCost(monthlySalary, wdH, 'weekday');
  const rdPay = calcOvertimeCost(monthlySalary, rdH, 'restday');
  const total = wdPay + rdPay;
  addStep(trace, { label: '平日部分（60%）', formula: "calcOvertimeCost(…, 'weekday')", inputs: { hours: wdH }, value: wdPay });
  addStep(trace, { label: '休息日部分（40%）', formula: "calcOvertimeCost(…, 'restday')", inputs: { hours: rdH }, value: rdPay });
  addStep(trace, { label: '混合加班費總計', formula: 'wdPay + rdPay', value: total });
  setSummary(trace, `混合加班 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元`);
  verify(total, monthlySalary, hours, type);
  return { result: total, trace };
}

function verify(traced, monthlySalary, hours, type, overridden = false) {
  // 有 override 時不強斷（結果本就不同）；只在純法規計算時保一致性
  if (overridden) return;
  const ref = calcOvertimeCost(monthlySalary, hours, type);
  if (Math.abs(ref - traced) > 0.01) {
    throw new Error(
      `overtime-traced 結果與 overtime.calcOvertimeCost 不一致（${type}, ${hours}h）：traced=${traced}, ref=${ref}`
    );
  }
}

/** 幫有 override 的 rule 補 addLaw 條目（標註為「院內規範」） */
function addOverrideLaws(trace, resolved, labels) {
  resolved.forEach((r, i) => {
    if (r.overridden) {
      addLaw(trace, {
        article: r.sourceRef ?? '院內規範（優於法規）',
        description: `${labels[i]}：貴院倍率 ${r.value}` + (r.note ? ' · ' + r.note : ''),
      });
    }
  });
}
