/**
 * severance-traced.js — 資遣費帶計算過程版本
 *
 * 本 module 輸出 `{ result, trace }`，給 HR Pro 展開「步驟 + 法源」UI。
 * 民眾版 laborpro 繼續用 `severance.js` 原函式，不受影響。
 */

import { calcSeveranceNew, calcSeveranceOld, calcNotice } from './severance.js';
import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { resolveSeveranceBase, resolveSeveranceCap, LEGAL_FLOOR } from './overrides.js';

/**
 * 新制資遣費帶 trace（HR-UX-1: 接受 options.overrides 院內規範覆寫）
 *
 * @param {number} totalMonths
 * @param {number} avgWage
 * @param {Object} [options]
 * @param {Object} [options.overrides]  workspace_override_rules map（見 overrides.js resolveValue）
 * @returns {import('./trace.js').TracedResult}
 */
export function calcSeveranceNewTraced(totalMonths, avgWage, options = {}) {
  const trace = createTrace();

  addLaw(trace, {
    article: '勞退條例§12',
    description: '每滿 1 年發 0.5 個月平均薪資，最高 6 個月',
  });

  const basePerYear = resolveSeveranceBase(options.overrides);
  const capMonths = resolveSeveranceCap(options.overrides);

  // 若有 override，補上「貴院規範」這條 law entry + 步驟標示
  if (basePerYear.overridden) {
    addLaw(trace, {
      article: basePerYear.sourceRef ?? '院內規範（優於法規）',
      description: `資遣基數 ${basePerYear.value} 月/年（法規 ${LEGAL_FLOOR.severance_base_per_year_months}）${basePerYear.note ? ' · ' + basePerYear.note : ''}`,
    });
  }
  if (capMonths.overridden) {
    addLaw(trace, {
      article: capMonths.sourceRef ?? '院內規範（優於法規）',
      description: `資遣上限 ${capMonths.value} 個月（法規 ${LEGAL_FLOOR.severance_cap_months}）${capMonths.note ? ' · ' + capMonths.note : ''}`,
    });
  }

  const years = totalMonths / 12;
  const rawMonths = years * basePerYear.value;
  const cappedMonths = Math.min(rawMonths, capMonths.value);
  const result = cappedMonths * avgWage;

  addStep(trace, {
    label: '服務年資換算',
    formula: 'totalMonths / 12',
    inputs: { totalMonths },
    value: years,
    note: '服務總月數除以 12 得服務年數（含小數）',
  });

  addStep(trace, {
    label: '基數計算',
    formula: `years × ${basePerYear.value}`,
    inputs: { years },
    value: rawMonths,
    note:
      `每滿 1 年 = ${basePerYear.value} 個月平均薪資` +
      (basePerYear.overridden ? `（貴院規範，法規下限 ${LEGAL_FLOOR.severance_base_per_year_months}）` : ''),
  });

  if (rawMonths > capMonths.value) {
    addStep(trace, {
      label: '上限套用',
      formula: `min(basis, ${capMonths.value})`,
      inputs: { basis: rawMonths },
      value: cappedMonths,
      note:
        (capMonths.overridden
          ? `貴院上限 ${capMonths.value} 個月（優於法規 ${LEGAL_FLOOR.severance_cap_months}）`
          : '勞退條例§12 明定最高 6 個月') + '，超過部分不計',
    });
  }

  addStep(trace, {
    label: '資遣費金額',
    formula: 'basis × avgWage',
    inputs: { basis: cappedMonths, avgWage },
    value: result,
  });

  setSummary(
    trace,
    `新制資遣費 ${Math.round(result).toLocaleString()} 元（基數 ${cappedMonths.toFixed(2)} 個月 × 平均薪資 ${Math.round(avgWage).toLocaleString()} 元）` +
      (basePerYear.overridden || capMonths.overridden ? ' · 套用院內規範' : '')
  );

  // 驗證（只在無 override 時與原函式一致；override 時法規版作為對照但不強斷）
  if (!basePerYear.overridden && !capMonths.overridden) {
    const ref = calcSeveranceNew(totalMonths, avgWage);
    if (Math.abs(ref - result) > 0.01) {
      throw new Error(
        `severance-traced 新制結果與 severance.calcSeveranceNew 不一致：traced=${result}, ref=${ref}`
      );
    }
  }

  return { result, trace };
}

/**
 * 舊制資遣費帶 trace
 * @param {number} totalMonths
 * @param {number} avgWage
 * @returns {import('./trace.js').TracedResult}
 */
export function calcSeveranceOldTraced(totalMonths, avgWage) {
  const trace = createTrace();

  addLaw(trace, {
    article: '勞基法§17',
    description: '舊制每滿 1 年發 1 個月平均薪資，不足 1 年按比例，無上限',
  });

  const years = totalMonths / 12;
  const result = years * avgWage;

  addStep(trace, {
    label: '服務年資換算',
    formula: 'totalMonths / 12',
    inputs: { totalMonths },
    value: years,
    note: '舊制不足 1 年按比例計算',
  });

  addStep(trace, {
    label: '基數計算',
    formula: 'years × 1',
    inputs: { years },
    value: years,
    note: '舊制每滿 1 年 = 1 個月，無上限',
  });

  addStep(trace, {
    label: '資遣費金額',
    formula: 'basis × avgWage',
    inputs: { basis: years, avgWage },
    value: result,
  });

  setSummary(
    trace,
    `舊制資遣費 ${Math.round(result).toLocaleString()} 元（基數 ${years.toFixed(2)} 個月 × 平均薪資 ${Math.round(avgWage).toLocaleString()} 元）`
  );

  const ref = calcSeveranceOld(totalMonths, avgWage);
  if (Math.abs(ref - result) > 0.01) {
    throw new Error(
      `severance-traced 舊制結果與 severance.calcSeveranceOld 不一致：traced=${result}, ref=${ref}`
    );
  }

  return { result, trace };
}

/**
 * 預告工資帶 trace
 * @param {number} calendarMonths
 * @param {number} avgWage
 * @returns {{ result: { days: number, amount: number, label: string }, trace: import('./trace.js').CalcTrace }}
 */
export function calcNoticeTraced(calendarMonths, avgWage) {
  const trace = createTrace();
  addLaw(trace, {
    article: '勞基法§16',
    description: '依年資不同，雇主終止契約前應於 10/20/30 日前預告',
  });

  addStep(trace, {
    label: '年資判定',
    formula: '依 calendarMonths 套 §16 三段式',
    inputs: { calendarMonths },
    value: calendarMonths,
  });

  const result = calcNotice(calendarMonths, avgWage);

  addStep(trace, {
    label: '預告天數',
    formula: result.label,
    value: result.days,
    note: result.label,
  });

  addStep(trace, {
    label: '未預告應發工資',
    formula: 'avgWage / 30 × days',
    inputs: { avgWage, days: result.days },
    value: result.amount,
    note: '若雇主未依§16 預告而逕行終止，應發此金額',
  });

  setSummary(
    trace,
    result.days === 0
      ? '未滿 3 個月，無須預告'
      : `預告 ${result.days} 日；未預告須發 ${Math.round(result.amount).toLocaleString()} 元`
  );

  return { result, trace };
}
