/**
 * dates.js — 日期與年資計算（純函式 ES module 版，從 laborpro/js/calc-utils.js 抽離）
 *
 * ## 法源與版本
 * - 勞基法§17（資遣費按比例）、§17-1（平均工資）
 * - 勞退條例§12（細則以「日」計）
 * - 最高法院 100 台上 1546
 *
 * 任何動這裡的函式必須同步通過 laborpro 現場頁面驗證，不得改變語意。
 */

/**
 * 以台北時區解析 'YYYY-MM-DD' 字串為 Date 物件
 * 避免 `new Date('YYYY-MM-DD')` 被當 UTC 造成 ±1 日誤差
 */
export function parseDateTW(s) {
  if (!s) return new Date(NaN);
  if (s instanceof Date) return s;
  const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return new Date(s);
  const [, y, mo, d] = m;
  // 構造本地時區 date（避免 UTC 詮釋）
  return new Date(Number(y), Number(mo) - 1, Number(d));
}

/**
 * 計算兩個日期之間的年月日差距
 *
 * 年資計算：改以 `totalDays / 365` 換算，避免「日/30 再 月/12」雙重折算誤差。
 * 實務上勞退條例§12 細則以「日」計；勞基法§17 亦以「日」換算（見最高法院 100 台上 1546）。
 *
 * @param {string|Date} fromStr
 * @param {string|Date} toStr
 * @returns {{ years: number, months: number, days: number, totalMonths: number, totalDays: number, serviceYears: number, fullCalendarMonths: number }}
 */
export function calcMonths(fromStr, toStr) {
  const d1 = parseDateTW(fromStr);
  const d2 = parseDateTW(toStr);
  if (isNaN(d1.getTime()) || isNaN(d2.getTime()) || d2 <= d1) {
    return { years: 0, months: 0, days: 0, totalMonths: 0, totalDays: 0, serviceYears: 0, fullCalendarMonths: 0 };
  }

  let years = d2.getFullYear() - d1.getFullYear();
  let months = d2.getMonth() - d1.getMonth();
  let days = d2.getDate() - d1.getDate();

  if (days < 0) {
    months--;
    const prev = new Date(d2.getFullYear(), d2.getMonth(), 0);
    days += prev.getDate();
  }
  if (months < 0) { years--; months += 12; }

  const totalDays = Math.round((d2.getTime() - d1.getTime()) / (1000 * 60 * 60 * 24));
  // 年資（法定計算基礎）：以自然日 / 365 換算（勞基法§84-2 實務），避免 30/365 混用誤差
  const serviceYears = totalDays / 365;
  // 向下相容：舊 callers 預期的 totalMonths（非實際月曆月份，而是 serviceYears × 12）
  const totalMonths = serviceYears * 12;
  // fullCalendarMonths：以月曆整月計（years*12 + months，day-of-month 未滿回補 -1）。
  //   適用於門檻型條文（§38 特休、§16 預告期間）之「滿 X 個月」判斷，
  //   避免 totalDays/365*12 換算於邊界日造成 ±3 天偏差。
  const fullCalendarMonths = years * 12 + months;

  return {
    years, months, days,
    totalMonths,
    totalDays,
    serviceYears,
    fullCalendarMonths,
  };
}
